boolean isPalindrome (String s) {
    int n = s.length ();
    for (int i = 0;
    i < (n / 2); ++ i) {
        if (s.charAt (i) != s.charAt (n - i - 1)) {
            return false;
        }
    }
    return true;
}


boolean isPalindrome(String str) {
    int len = str.length();
    int lastIndex = len - 1;
    for (int i = 0; i < (len / 2); i++) {
        if (str.charAt(i) != str.charAt(lastIndex - i)) {
            return false;
        }
    }
    return true;
